"""Present the staged diagnostic JSON without altering its fail-fast results."""
from pathlib import Path
import json,html
p=Path(__file__).resolve().parent;repo=p.parents[2];d=json.loads((p/'diagnosis.json').read_text())
style=(repo/'runs/pipeline_v1/final/report.html').read_text().split('<style>',1)[1].split('</style>',1)[0]
stages=''.join(f"<tr><td>{s['name']}</td><td class={'ok' if s['status']=='PASS' else 'badc'}>{s['status']}</td><td>{html.escape(s['reason'])}</td></tr>" for s in d['stages'])
a=next(s['measurements'] for s in d['stages'] if s['name'].startswith('1-'));b=next(s['measurements'] for s in d['stages'] if s['name'].startswith('2-'));c=next(s['measurements'] for s in d['stages'] if s['name'].startswith('3a-'))
original=''.join(f"<tr><td>{r['source']}</td><td>{r['attempted']}</td><td>{r['accepted']}</td><td>{html.escape(str(r['rejected_reasons']))}</td></tr>" for r in a['sources'])
generated=''.join(f"<tr><td>scale {r['scale']}</td><td>{r['S0_height_m']:.6f} m</td><td>{r['physics']['max_foot_penetration_mm']:.3f} mm</td><td>{r['physics']['nonfoot_penetration_mm']:.3f} mm</td><td>{r['reproduction_foot_height_error_mm']:.6f} mm</td></tr>" for r in c['candidates'])
maxfoot=max(r['foot_height_error_mm'] for r in b['probes']);maxtoken=max(r['token_error'] for r in b['probes'])
page=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>생성 초기 상태 관통 원인 진단</title><style>{style}a{{color:var(--acc)}}</style></head><body><main><header><h1>생성 E·S₀ 관통 원인 진단</h1><div class="sub">2026-10-22 · 코드 7d589f2d7 · CPU MuJoCo 검사 · 기존 데이터와 생성 결과 재사용</div></header><nav><a href="#summary">요약</a><a href="#stages">단계 결과</a><a href="#real">실제 상태·변환</a><a href="#generated">생성 결과</a><a href="#limits">해석·한계</a><a href="#files">원자료</a></nav>
<h2 id="summary">요약</h2><div class="box bad"><b>생성 E·S₀ 두 쌍의 물리적 불일치 재확인</b>선택된 정상 실제 상태 9개는 변환·복원을 통과했고, 저장된 Smoke의 발 높이도 재현했습니다. 따라서 이 표본의 수 cm 관통은 변환 경로의 일반적 오류보다는 생성된 형상·초기 자세 조합에서 발생한 것으로 좁혀집니다. 모델 내부의 구체적 원인은 아직 확정하지 않았습니다.</div>
<h2 id="stages">단계별 검사</h2><div class="tw"><table><thead><tr><th>단계</th><th>결과</th><th>근거</th></tr></thead><tbody>{stages}</tbody></table></div><p>실행기는 3b 실패를 기록하고 종료 코드 1로 중단했습니다. 이는 진단 실행 오류가 아니라 예상된 물리 검사 실패 판정입니다. 관련 단위 테스트는 8개 통과했습니다.</p>
<h2 id="real">실제 데이터와 변환 경로</h2><div class="tw"><table><thead><tr><th>형상</th><th>검사 프레임</th><th>정상 프레임 확보</th><th>탈락 사유 집계</th></tr></thead><tbody>{original}</tbody></table></div><div class="box note"><b>정상 프레임을 찾았다는 의미이며, 원본 데이터 전체 정상 판정은 아님</b>각 형상에서 4개를 검사해 3개를 확보했습니다. 전체 12개 중 3개는 발 관통으로 탈락했습니다. 정상으로 선정한 9개만 다음 변환 검사에 사용했습니다.</div><p>실제 qpos·qvel → TT features → 공유 s0_to_q → MuJoCo 검사에서 9/9 통과했습니다. 발 높이 최대 오차는 기록 정밀도 기준 {maxfoot:.6f} mm, 토큰 최대 오차는 {maxtoken:.8f}입니다. 이 결과는 선택된 표본에 한정됩니다.</p>
<h2 id="generated">저장된 생성 E·S₀ 재현</h2><div class="tw"><table><thead><tr><th>후보</th><th>생성 몸통 높이</th><th>최대 발 관통</th><th>비발 지면 관통</th><th>기존 Smoke 발 높이 대비 최대 오차</th></tr></thead><tbody>{generated}</tbody></table></div><p>두 후보 모두 발과 비발 지면 관통으로 실패했습니다. 재현 오차는 허용 1 mm보다 작으며, 관통 기준 2 mm는 변경하지 않았습니다. 높이 이동도 적용하지 않았습니다.</p>
<h2 id="limits">무엇이 확인됐고 무엇이 남았는가</h2><ul><li>정상 실제 데이터는 현재 모델·변환 경로에서도 정상으로 복원됩니다.</li><li>저장된 Smoke 관통이 같은 geometry에서 재현되므로, 이번 결과를 단순한 실험 설정 차이로 설명할 근거는 없습니다.</li><li>생성 E·몸통 높이·관절각이 함께 물리 조건을 충족하지 못했습니다. E 하나 또는 높이 하나만을 원인으로 확정하지 않습니다.</li><li>두 후보의 높이가 동일하게 0.155553 m인 것은 관측 사실입니다. 그 이유가 정규화·clamp·학습·sampling 중 무엇인지 이번 코드는 분리하지 않습니다.</li><li>원본 데이터에도 일부 관통이 관측됐습니다. 학습 데이터의 관통 분포와 생성 결과를 더 넓게 비교해야 합니다.</li><li>다음 후보 진단: 여러 seed의 무guidance 생성 유효율, E별 높이·관절각 정합성, 생성 높이의 정규화/clamp 위치를 확인합니다.</li></ul><p>추가 학습·새 공동 생성·MJX 시간 stepping은 수행하지 않았습니다. 진단 대상은 기본 e000/e001/e002와 기존 seed 0의 생성 두 쌍입니다.</p>
<h2 id="files">원자료와 재현</h2><ul><li><a href="diagnosis.json">단계별 수치·개별 검사 원자료</a></li><li><a href="../fast_mode24_v4_smoke_audit/report.html">선행 Smoke HTML 보고서</a></li><li><a href="make_report.py">보고서 생성 코드</a></li></ul><pre><code>../transformer-transformer/.venv/bin/python code/tt_dynamics/diagnose_s0_penetration.py</code></pre></main></body></html>'''
(p/'report.html').write_text(page);print(p/'report.html')
